-- Adds original inline SVG visuals to Year 3, Week 1, Lesson 1: Reading with expression.
-- QuestVisual renders { svg, alt, caption }. Two of these use SMIL animation (no scripts).
-- SVG attributes use single quotes, doubled here because this is a SQL string.
UPDATE lessons
SET data = json_set(
  data,
  '$.teach_steps[0].visual',
  json('[{"alt":"Two lines. A robot voice is a flat straight line. An expressive voice is a wavy line that goes up and down.","caption":"Watch the dots. The robot voice stays flat. An expressive voice goes up and down to show meaning.","svg":"<svg xmlns=''http://www.w3.org/2000/svg'' viewBox=''0 0 460 230'' font-family=''sans-serif''><rect width=''460'' height=''230'' rx=''14'' fill=''#F7FAFF''/><text x=''20'' y=''28'' font-size=''18'' font-weight=''bold'' fill=''#555''>Robot voice</text><line x1=''20'' y1=''70'' x2=''440'' y2=''70'' stroke=''#999'' stroke-width=''4'' stroke-linecap=''round''/><circle r=''9'' fill=''#777''><animateMotion dur=''4s'' repeatCount=''indefinite'' path=''M20,70 L440,70''/></circle><text x=''20'' y=''128'' font-size=''18'' font-weight=''bold'' fill=''#2E7D32''>Expressive voice</text><path d=''M20,180 C70,125 110,235 160,180 S250,125 300,180 S390,235 440,180'' fill=''none'' stroke=''#2E7D32'' stroke-width=''4'' stroke-linecap=''round''/><circle r=''9'' fill=''#F5A623''><animateMotion dur=''4s'' repeatCount=''indefinite'' path=''M20,180 C70,125 110,235 160,180 S250,125 300,180 S390,235 440,180''/></circle></svg>"}]'),
  '$.teach_steps[1].visual',
  json('[{"alt":"Four cards. A full stop means pause and let the voice fall. A comma means a short pause. A question mark means the voice rises. An exclamation mark means a stronger voice with feeling.","caption":"Punctuation tells your voice what to do.","svg":"<svg xmlns=''http://www.w3.org/2000/svg'' viewBox=''0 0 480 230'' font-family=''sans-serif''><rect x=''10'' y=''10'' width=''220'' height=''100'' rx=''12'' fill=''#E8F1FB''/><text x=''30'' y=''68'' font-size=''52'' font-weight=''bold'' fill=''#1F4E8C''>.</text><text x=''75'' y=''48'' font-size=''16'' font-weight=''bold'' fill=''#1F4E8C''>Full stop</text><text x=''75'' y=''72'' font-size=''14'' fill=''#333''>Pause. Voice falls.</text><rect x=''250'' y=''10'' width=''220'' height=''100'' rx=''12'' fill=''#FFF4D6''/><text x=''270'' y=''68'' font-size=''52'' font-weight=''bold'' fill=''#9A6B00''>,</text><text x=''315'' y=''48'' font-size=''16'' font-weight=''bold'' fill=''#9A6B00''>Comma</text><text x=''315'' y=''72'' font-size=''14'' fill=''#333''>Short pause.</text><text x=''315'' y=''92'' font-size=''14'' fill=''#333''>Voice stays up.</text><rect x=''10'' y=''120'' width=''220'' height=''100'' rx=''12'' fill=''#E6F6EA''/><text x=''30'' y=''188'' font-size=''52'' font-weight=''bold'' fill=''#2E7D32''>?</text><text x=''75'' y=''158'' font-size=''16'' font-weight=''bold'' fill=''#2E7D32''>Question mark</text><text x=''75'' y=''182'' font-size=''14'' fill=''#333''>Voice rises</text><text x=''75'' y=''202'' font-size=''14'' fill=''#333''>at the end.</text><rect x=''250'' y=''120'' width=''220'' height=''100'' rx=''12'' fill=''#FDE8E8''/><text x=''270'' y=''188'' font-size=''52'' font-weight=''bold'' fill=''#B3261E''>!</text><text x=''315'' y=''158'' font-size=''16'' font-weight=''bold'' fill=''#B3261E''>Exclamation mark</text><text x=''315'' y=''182'' font-size=''14'' fill=''#333''>Stronger voice,</text><text x=''315'' y=''202'' font-size=''14'' fill=''#333''>show feeling.</text></svg>"}]'),
  '$.teach_steps[2].visual',
  json('[{"alt":"The sentence The tired puppy curled up in the warm sun split into three colour groups: who is the tired puppy, what it did is curled up, and where is in the warm sun.","caption":"Read each group smoothly. Pause between groups, not inside them.","svg":"<svg xmlns=''http://www.w3.org/2000/svg'' viewBox=''0 0 480 140'' font-family=''sans-serif''><text x=''240'' y=''22'' font-size=''15'' text-anchor=''middle'' fill=''#444''>Read each group smoothly. Pause between groups.</text><rect x=''10'' y=''40'' width=''170'' height=''50'' rx=''12'' fill=''#DDEBFF'' stroke=''#1F4E8C'' stroke-width=''2''/><text x=''95'' y=''71'' font-size=''17'' text-anchor=''middle'' fill=''#1F4E8C''>The tired puppy</text><rect x=''192'' y=''40'' width=''110'' height=''50'' rx=''12'' fill=''#FFE9C7'' stroke=''#9A6B00'' stroke-width=''2''/><text x=''247'' y=''71'' font-size=''17'' text-anchor=''middle'' fill=''#9A6B00''>curled up</text><rect x=''314'' y=''40'' width=''156'' height=''50'' rx=''12'' fill=''#DDF3E0'' stroke=''#2E7D32'' stroke-width=''2''/><text x=''392'' y=''71'' font-size=''17'' text-anchor=''middle'' fill=''#2E7D32''>in the warm sun</text><text x=''95'' y=''118'' font-size=''14'' text-anchor=''middle'' fill=''#555''>who</text><text x=''247'' y=''118'' font-size=''14'' text-anchor=''middle'' fill=''#555''>did what</text><text x=''392'' y=''118'' font-size=''14'' text-anchor=''middle'' fill=''#555''>where</text></svg>"}]'),
  '$.teach_steps[5].visual',
  json('[{"alt":"The sentence I did not take your pencil. A yellow highlight moves from word to word and a line below shows how the meaning changes with each stressed word.","caption":"Watch the highlight. The stressed word changes the meaning. Say each version out loud.","svg":"<svg xmlns=''http://www.w3.org/2000/svg'' viewBox=''0 0 450 200'' font-family=''sans-serif''><rect width=''450'' height=''200'' rx=''14'' fill=''#FFFDF5''/><text x=''225'' y=''26'' font-size=''14'' text-anchor=''middle'' fill=''#666''>Say the highlighted word a little stronger</text><rect y=''42'' width=''70'' height=''44'' rx=''10'' fill=''#FFD966''><animate attributeName=''x'' values=''5;60;120;190;265;350'' dur=''12s'' calcMode=''discrete'' repeatCount=''indefinite''/></rect><text x=''40'' y=''72'' font-size=''20'' text-anchor=''middle'' fill=''#222''>I</text><text x=''95'' y=''72'' font-size=''20'' text-anchor=''middle'' fill=''#222''>did</text><text x=''155'' y=''72'' font-size=''20'' text-anchor=''middle'' fill=''#222''>not</text><text x=''225'' y=''72'' font-size=''20'' text-anchor=''middle'' fill=''#222''>take</text><text x=''300'' y=''72'' font-size=''20'' text-anchor=''middle'' fill=''#222''>your</text><text x=''385'' y=''72'' font-size=''20'' text-anchor=''middle'' fill=''#222''>pencil</text><text x=''225'' y=''142'' font-size=''19'' font-weight=''bold'' text-anchor=''middle'' fill=''#1F4E8C'' opacity=''1''>Someone else took it.<animate attributeName=''opacity'' values=''1;0;0;0;0;0'' dur=''12s'' calcMode=''discrete'' repeatCount=''indefinite''/></text><text x=''225'' y=''142'' font-size=''19'' font-weight=''bold'' text-anchor=''middle'' fill=''#1F4E8C'' opacity=''0''>Stop saying that I did.<animate attributeName=''opacity'' values=''0;1;0;0;0;0'' dur=''12s'' calcMode=''discrete'' repeatCount=''indefinite''/></text><text x=''225'' y=''142'' font-size=''19'' font-weight=''bold'' text-anchor=''middle'' fill=''#1F4E8C'' opacity=''0''>I definitely did not.<animate attributeName=''opacity'' values=''0;0;1;0;0;0'' dur=''12s'' calcMode=''discrete'' repeatCount=''indefinite''/></text><text x=''225'' y=''142'' font-size=''19'' font-weight=''bold'' text-anchor=''middle'' fill=''#1F4E8C'' opacity=''0''>Maybe I only borrowed it.<animate attributeName=''opacity'' values=''0;0;0;1;0;0'' dur=''12s'' calcMode=''discrete'' repeatCount=''indefinite''/></text><text x=''225'' y=''142'' font-size=''19'' font-weight=''bold'' text-anchor=''middle'' fill=''#1F4E8C'' opacity=''0''>I took someone elses pencil.<animate attributeName=''opacity'' values=''0;0;0;0;1;0'' dur=''12s'' calcMode=''discrete'' repeatCount=''indefinite''/></text><text x=''225'' y=''142'' font-size=''19'' font-weight=''bold'' text-anchor=''middle'' fill=''#1F4E8C'' opacity=''0''>I took something else of yours.<animate attributeName=''opacity'' values=''0;0;0;0;0;1'' dur=''12s'' calcMode=''discrete'' repeatCount=''indefinite''/></text><text x=''225'' y=''182'' font-size=''13'' text-anchor=''middle'' fill=''#777''>Same words. Different stress. Different meaning.</text></svg>"}]')
)
WHERE seed_key = 's2-eng-y3-w01-l1';
